B.aiy=new A.D("\u30b8\u30a2\u30bc\u30d1\u30e0 (DZP)","\u30bb\u30eb\u30b7\u30f3 / \u30db\u30ea\u30be\u30f3",B.y,"\u30bb\u30eb\u30b7\u30f3\u93202mg, 5mg, 10mg, \u30bb\u30eb\u30b7\u30f3\u65631%, \u30bb\u30eb\u30b7\u30f3\u30b7\u30ed\u30c3\u30d70.1%, \u30bb\u30eb\u30b7\u30f3\u6ce8\u5c04\u6db25mg (1mL), \u30bb\u30eb\u30b7\u30f3\u6ce8\u5c04\u6db210mg (2mL)","\u539f\u5247\u3068\u3057\u3066\u5e0c\u91c8\u305b\u305a\u539f\u6db2\u306e\u307e\u307e\u3067\u304d\u308b\u3060\u3051\u7de9\u5f90\u306b (2\u5206\u9593\u4ee5\u4e0a\u304b\u3051\u3066) \u9759\u6ce8\u307e\u305f\u306f\u7b4b\u6ce8\u3059\u308b. \u6eb6\u89e3\u88dc\u52a9\u5264\u306b\u975e\u6c34\u6027\u306e\u6709\u6a5f\u6eb6\u5a92\u3092\u542b\u307f, \u4ed6\u306e\u6ce8\u5c04\u5264\u3068\u6df7\u5408\u3059\u308b\u3068\u6df7\u6fc1\u30fb\u6790\u51fa\u3092\u8d77\u3053\u3059\u3053\u3068\u304c\u3042\u308b\u305f\u3081\u5358\u72ec\u6295\u4e0e\u3068\u3057, \u9759\u8108\u708e\u3092\u907f\u3051\u308b\u305f\u3081\u592a\u3044\u9759\u8108\u3092\u9078\u3076","\u6ce8\u5c04\u6db2\u306f5mg/mL\u3067\u7d71\u4e00 (5mg\u88fd\u5264\u306f1mL, 10mg\u88fd\u5264\u306f2mL)","\u30fb\u795e\u7d4c\u75c7\u306b\u304a\u3051\u308b\u4e0d\u5b89\u30fb\u7dca\u5f35\u30fb\u6291\u3046\u3064 (\u5185\u670d): \u901a\u5e38\u6210\u4eba1\u56de2-5mg\u30921\u65e52-4\u56de\u7d4c\u53e3\u6295\u4e0e, \u5916\u6765\u60a3\u8005\u306f\u539f\u52471\u65e515mg\u4ee5\u5185\n\u30fb\u5c0f\u5150\u306e\u795e\u7d4c\u75c7 (\u5185\u670d): 3\u6b73\u4ee5\u4e0b1\u65e51-5mg, 4-12\u6b731\u65e52-10mg\u30921-3\u56de\u306b\u5206\u5272\u7d4c\u53e3\u6295\u4e0e\n\u30fb\u3066\u3093\u304b\u3093\u306e\u75d9\u6523\u767a\u4f5c, \u7b4b\u75d9\u6523 (\u5185\u670d): \u901a\u5e38\u6210\u4eba1\u56de2-10mg\u30921\u65e53-4\u56de\u7d4c\u53e3\u6295\u4e0e\n\u30fb\u795e\u7d4c\u75c7, \u9ebb\u9154\u524d\u5f8c\u30fb\u8853\u5f8c\u306e\u4e0d\u5b89\u8208\u596e, \u3066\u3093\u304b\u3093\u69d8\u91cd\u7a4d\u72b6\u614b\u306e\u75d9\u6523\u6291\u5236, \u5206\u5a29\u6642\u306e\u4e0d\u5b89\u9664\u53bb, \u30a2\u30eb\u30b3\u30fc\u30eb\u96e2\u8131\u75c7\u72b6 (\u6ce8\u5c04): \u6210\u4eba\u306f\u521d\u56de2mL (\u30b8\u30a2\u30bc\u30d1\u30e0\u3068\u3057\u306610mg) \u3092\u7b4b\u8089\u5185\u53c8\u306f\u9759\u8108\u5185\u306b\u3067\u304d\u308b\u3060\u3051\u7de9\u5f90\u306b\u6ce8\u5c04\u3057, \u4ee5\u5f8c\u5fc5\u8981\u306b\u5fdc\u3058\u30663-4\u6642\u9593\u3054\u3068\u306b\u6ce8\u5c04\n\u30fb\u9759\u8108\u5185\u6ce8\u5c04\u6642\u306f\u306a\u308b\u3079\u304f\u592a\u3044\u9759\u8108\u3092\u9078\u3073, 2\u5206\u9593\u4ee5\u4e0a\u304b\u3051\u3066\u7de9\u5f90\u306b\u6ce8\u5c04\u3059\u308b\n\u30fb\u5c0f\u5150\u3078\u306e\u7b4b\u8089\u5185\u6ce8\u5c04\u306f\u884c\u308f\u306a\u3044",B.Xd,"\u3066\u3093\u304b\u3093\u91cd\u7a4d\u72b6\u614b: \u30b8\u30a2\u30bc\u30d1\u30e0\u6ce85-10mg\u30922\u5206\u9593\u4ee5\u4e0a\u304b\u3051\u3066\u7de9\u5f90\u306b\u9759\u6ce8\u3059\u308b (\u7b2c\u4e00\u9078\u629e\u85ac\u306e\u4e00\u3064). \u547c\u5438\u6291\u5236\u30fb\u5faa\u74b0\u6291\u5236\u306b\u6ce8\u610f\u3057, \u8ffd\u52a0\u6295\u4e0e\u3092\u7e70\u308a\u8fd4\u3059\u969b\u306f\u7279\u306b\u6ce8\u610f\u6df1\u304f\u89b3\u5bdf\u3059\u308b. \u30a2\u30eb\u30b3\u30fc\u30eb\u96e2\u8131\u75c7\u72b6\u306e\u3051\u3044\u308c\u3093\u30fb\u632f\u6226\u305b\u3093\u5984\u4e88\u9632\u306b\u3082\u7528\u3044\u3089\u308c\u308b",null,null,"\u5185\u670d\u30fb\u6ce8\u5c04\u5264\u306e\u4e21\u65b9\u304c\u3042\u308a, \u5e38\u7528\u8005\u306f\u539f\u5247\u3068\u3057\u3066\u624b\u8853\u5f53\u65e5\u671d\u307e\u3067\u7d99\u7d9a\u3057, \u8853\u5f8c\u3082\u7d4c\u53e3\u6442\u53d6\u304c\u518d\u958b\u3067\u304d\u6b21\u7b2c\u901f\u3084\u304b\u306b\u518d\u958b\u3059\u308b. \u6025\u306a\u4e2d\u6b62\u306b\u3088\u308b\u96e2\u8131\u75c7\u72b6 (\u75d9\u6523, \u305b\u3093\u5984, \u632f\u6226, \u4e0d\u5b89, \u4e0d\u7720) \u3092\u907f\u3051\u308b\u305f\u3081\u81ea\u5df1\u5224\u65ad\u3067\u4f11\u85ac\u3055\u305b\u306a\u3044. \u6ce8\u5c04\u5264\u304c\u3042\u308b\u305f\u3081, \u5185\u670d\u4e0d\u80fd\u306a\u671f\u9593\u306f\u30b8\u30a2\u30bc\u30d1\u30e0\u6ce8\u3067\u7d99\u7d9a\u3084, \u3066\u3093\u304b\u3093\u91cd\u7a4d\u30fb\u30a2\u30eb\u30b3\u30fc\u30eb\u96e2\u8131\u306e\u4e88\u9632\u6295\u4e0e\u306b\u3082\u5229\u7528\u3067\u304d\u308b. \u4e00\u65b9\u3067\u6d3b\u6027\u4ee3\u8b1d\u7269 (\u30ce\u30eb\u30b8\u30a2\u30bc\u30d1\u30e0\u306a\u3069) \u3092\u3082\u3064\u9577\u6642\u9593\u4f5c\u7528\u578bBZ\u7cfb\u85ac\u3067\u3042\u308a, \u53cd\u5fa9\u6295\u4e0e\u3084\u9ad8\u9f62\u8005\u3067\u306f\u84c4\u7a4d\u306b\u3088\u308b\u904e\u93ae\u9759\u30fb\u8853\u5f8c\u305b\u3093\u5984\u304c\u9077\u5ef6\u3057\u3084\u3059\u3044\u305f\u3081, \u9ad8\u9f62\u8005\u3078\u306e\u65b0\u898f\u6295\u4e0e\u306f\u907f\u3051, \u53ef\u80fd\u3067\u3042\u308c\u3070\u77ed\u6642\u9593\u4f5c\u7528\u578b\u85ac\u3078\u306e\u5207\u66ff\u3092\u691c\u8a0e\u3059\u308b. \u9759\u8108\u708e\u3092\u907f\u3051\u308b\u305f\u3081\u592a\u3044\u9759\u8108\u304b\u3089\u7de9\u5f90\u306b\u6295\u4e0e\u3057, \u4ed6\u5264\u3068\u306e\u6df7\u6ce8\u306f\u907f\u3051\u308b","1,4-\u30d9\u30f3\u30be\u30b8\u30a2\u30bc\u30d4\u30f3\u7cfb. GABA-A\u53d7\u5bb9\u4f53\u306e\u30d9\u30f3\u30be\u30b8\u30a2\u30bc\u30d4\u30f3\u7d50\u5408\u90e8\u4f4d\u306b\u4f5c\u7528\u3057, GABA\u306e\u6291\u5236\u6027\u795e\u7d4c\u4f1d\u9054\u3092\u5897\u5f37\u3059\u308b. \u6d3b\u6027\u4ee3\u8b1d\u7269 (N-\u30c7\u30b9\u30e1\u30c1\u30eb\u30b8\u30a2\u30bc\u30d1\u30e0=\u30ce\u30eb\u30b8\u30a2\u30bc\u30d1\u30e0\u7b49) \u3092\u3082\u3061, \u6297\u4e0d\u5b89, \u6297\u3051\u3044\u308c\u3093, \u7b4b\u5f1b\u7de9, \u50ac\u7720\u4f5c\u7528\u3092\u3042\u308f\u305b\u3082\u3064\u9577\u6642\u9593\u4f5c\u7528\u578bBZ\u7cfb\u85ac",B.awf,!0,null,"https://medical.nikkeibp.co.jp/inc/all/drugdic/prd/11/1124402A2053.html",B.awT,B.at1)
B.XN=new A.X(!0,!0,"\u5185\u670d (\u93201mg, 2mg, \u4e0d\u7720\u75c7\u30fb\u9ebb\u9154\u524d\u6295\u85ac) \u3068\u6ce8\u5c04\u5264 (\u9759\u6ce82mg, \u5168\u8eab\u9ebb\u9154\u306e\u5c0e\u5165\u30fb\u5c40\u6240\u9ebb\u9154\u6642\u306e\u93ae\u9759) \u306e\u4e21\u65b9\u304c\u3042\u308b")
